#include <pthread.h> 
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

#define CHECK_SUCCESS(ret, msg) \
    if (ret != 0) { \
        fprintf(stderr, "%s failed: Error %d\n", msg, ret); \
        /* In a real application, handle cleanup before exit */ \
        exit(EXIT_FAILURE); \
    }

// Utility to convert the constant to a readable string
const char* inheritsched_to_str(int val) {
    if (val == PTHREAD_INHERIT_SCHED) return "PTHREAD_INHERIT_SCHED (Inherit)";
    if (val == PTHREAD_EXPLICIT_SCHED) return "PTHREAD_EXPLICIT_SCHED (Explicit)";
    return "Unknown Value";
}

int main() {
    pthread_attr_t attr;
    int ret, current_inheritsched;
    int desired_inheritsched = PTHREAD_EXPLICIT_SCHED;

    // 1. Initialize the thread attributes object
    ret = pthread_attr_init(&attr);
    CHECK_SUCCESS(ret, "pthread_attr_init");

    // 2. Get and display the default inheritance value
    ret = pthread_attr_getinheritsched(&attr, &current_inheritsched);
    CHECK_SUCCESS(ret, "pthread_attr_getinheritsched (initial)");
    printf("Default inheritance setting: %s\n", inheritsched_to_str(current_inheritsched));

    // 3. Set the inheritance mode to EXPLICIT
    printf("\nAttempting to set inheritance mode to EXPLICIT...\n");
    ret = pthread_attr_setinheritsched(&attr, desired_inheritsched);
    CHECK_SUCCESS(ret, "pthread_attr_setinheritsched");

    // 4. Verify the new value was set correctly
    ret = pthread_attr_getinheritsched(&attr, &current_inheritsched);
    CHECK_SUCCESS(ret, "pthread_attr_getinheritsched (final)");
    printf("Verification: New setting is %s\n", inheritsched_to_str(current_inheritsched));

    // 5. Clean up
    ret = pthread_attr_destroy(&attr);
    CHECK_SUCCESS(ret, "pthread_attr_destroy");

    return 0;
}
